import { useId } from "react";
import { cn } from "@/lib/utils";

/**
 * VaultDrop mark: a drop carrying a keyhole (the secret, locked) whose tip evaporates in two
 * slices (gone after it is read). Exact geometry — generated by splitting the drop's Bézier
 * flanks at the cut lines. The keyhole is cut out with even-odd fill so the page background
 * shows through. Colour comes from the --logo-* theme tokens in globals.css.
 */
const TIP = "M16 1.5C16 1.5 14.19 3.48 12.07 6.3H19.93C17.81 3.48 16 1.5 16 1.5Z";
const BAND = "M11.19 7.5C10.54 8.41 9.87 9.39 9.24 10.4H22.76C22.13 9.39 21.46 8.41 20.81 7.5Z";
const BODY =
  "M8.51 11.6C6.81 14.49 5.5 17.53 5.5 20A10.5 10.5 0 0 0 26.5 20C26.5 17.53 25.19 14.49 23.49 11.6Z" +
  "M13.85 26L14.75 22.12A3.2 3.2 0 1 1 17.25 22.12L18.15 26Z";
export const LOGO_MARK_PATH = TIP + BAND + BODY;
/** Drawn as separate parts so the slices can drift on hover (see .logo-slice in globals.css). */
const PARTS = [
  { d: TIP, className: "logo-slice logo-slice-tip" },
  { d: BAND, className: "logo-slice logo-slice-band" },
  { d: BODY, className: undefined },
];

/** Specular highlight: an arc concentric with the drop's body, upper-left, like light on liquid. */
export const LOGO_HIGHLIGHT_PATH = "M8.2 17.16A8.3 8.3 0 0 1 12.49 12.48";

export function LogoMark({ className }: { className?: string }) {
  // Gradient ids must be unique: the header and mobile menu can render the mark simultaneously.
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const fill = `vd-logo-fill-${uid}`;
  const sheen = `vd-logo-sheen-${uid}`;
  // Decorative: always rendered next to the "VaultDrop" wordmark or a page heading.
  return (
    <svg viewBox="0 0 32 32" className={cn("size-7", className)} aria-hidden="true">
      <defs>
        <linearGradient id={fill} x1="9" y1="2" x2="23" y2="31" gradientUnits="userSpaceOnUse">
          <stop offset="0" style={{ stopColor: "var(--logo-1)" }} />
          <stop offset="0.55" style={{ stopColor: "var(--logo-2)" }} />
          <stop offset="1" style={{ stopColor: "var(--logo-3)" }} />
        </linearGradient>
        <radialGradient id={sheen} cx="12" cy="15" r="13" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#fff" stopOpacity="0.35" />
          <stop offset="0.55" stopColor="#fff" stopOpacity="0" />
        </radialGradient>
      </defs>
      {PARTS.map((p) => (
        <g key={p.d} className={p.className}>
          <path d={p.d} fill={`url(#${fill})`} fillRule="evenodd" />
          <path d={p.d} fill={`url(#${sheen})`} fillRule="evenodd" />
        </g>
      ))}
      <path
        d={LOGO_HIGHLIGHT_PATH}
        fill="none"
        stroke="#fff"
        strokeOpacity="0.6"
        strokeWidth="1.2"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Logo({ className }: { className?: string }) {
  return (
    <span className={cn("vd-logo text-foreground inline-flex items-center gap-1.5", className)}>
      <LogoMark />
      <span className="text-[17px] font-semibold tracking-[-0.025em]">
        Vault
        {/* Gradient lettering echoes the mark; forced-colors mode falls back to solid text. */}
        <span className="bg-linear-135 from-(--logo-text-1) to-(--logo-text-2) bg-clip-text text-transparent forced-colors:bg-none forced-colors:text-[CanvasText]">
          Drop
        </span>
      </span>
    </span>
  );
}
